class Solution {
public:
    long long maximumTripletValue(vector<int>& nums) {
        long long ans = 0, max_i = 0, max_diff = 0;
        for (int x : nums) {
            ans = max(ans, max_diff * x);
            max_diff = max(max_diff, max_i - x);
            max_i = max(max_i, 1LL * x);
        }
        return ans;
    }
};

class Solution {
    public long maximumTripletValue(int[] nums) {
        long ans = 0, maxI = 0, maxDiff = 0;
        for (int x : nums) {
            ans = Math.max(ans, maxDiff * x);
            maxDiff = Math.max(maxDiff, maxI - x);
            maxI = Math.max(maxI, x);
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var maximumTripletValue = function(nums) {
    let ans = 0, maxI = 0, maxDiff = 0;
    for (const x of nums) {
        if (maxDiff * x > ans) ans = maxDiff * x;
        if (maxI - x > maxDiff) maxDiff = maxI - x;
        if (x > maxI) maxI = x;
    }
    return ans;
};
